INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2366, 2445, NULL, N'SP-GIAY-SNEAKER-08', N'Giày Sneaker Thể Thao Đệm Khí Êm Chân Simplain Runner', N'giay-sneaker-the-thao-dem-khi-simplain', N'Vải Flyknit thoáng khí', N'Low-Top cổ thấp', N'Giày sneaker thể thao với thân dệt Flyknit nguyên khối co giãn ôm sát mu bàn chân, đế đệm trợ lực êm ái bảo vệ khớp xương khi đi bộ hay chạy nhảy. Đế ngoài phủ cao su chống mài mòn và bám đường tối ưu.', N'Size 39: Chân 24.1 - 24.5cm | Size 40: 24.6 - 25.0cm | Size 41: 25.1 - 25.5cm | Size 42: 25.6 - 26.0cm', CAST(590000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.4466667' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2367, 2446, NULL, N'SP-GIAY-SANDAL-09', N'Giày Sandal Nam Nữ Quai Dù Đế Bánh Mì Siêu Êm', N'giay-sandal-nam-nu-quai-du-de-banh-mi', N'Cao su lưu hóa chống trơn', N'Low-Top cổ thấp', N'Sandal quai hậu bản dù jacquard chịu lực cao, khóa dán thông minh điều chỉnh độ ôm chân linh hoạt. Đế bánh mì đúc cao su non siêu nhẹ, êm ái chống trơn trượt hoàn hảo khi đi mưa.', N'Size 38: Chân dài 23.5 - 24.0cm | Size 39: 24.1 - 24.5cm | Size 40: 24.6 - 25.0cm | Size 41: 25.1 - 25.5cm', CAST(320000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.4600000' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2368, 2447, NULL, N'SP-GIAY-DEP-10', N'Dép Quai Ngang Đúc Nguyên Khối Chống Trơn Trượt Simplain', N'dep-quai-ngang-duc-nguyen-khoi', N'Cao su lưu hóa chống trơn', N'Loafer xỏ tiện lợi', N'Dép bánh mì quai ngang đúc nguyên khối từ hạt nhựa EVA cao cấp, trọng lượng siêu nhẹ và chống nước tuyệt đối. Đế vân gai kim cương chống trơn trượt an toàn cả trong nhà tắm lẫn đi dạo ngoài trời.', N'Size 39: Chân 24cm | Size 40: Chân 24.5-25cm | Size 41: Chân 25.5cm | Size 42: Chân 26cm', CAST(150000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.4700000' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2369, 2432, NULL, N'SP-TUI-XACH-11', N'Túi Xách Da Bò Epsom Nữ Khóa Gập Thanh Lịch Simplain', N'tui-xach-da-bo-epsom-nu-thanh-lich', N'Da bò hạt Epsom', N'Túi bao tử (Chest Bag)', N'Túi xách nữ chất liệu da bò Epsom dập vân tinh tế chống trầy xước và kháng nước, phụ kiện khóa xoay mạ vàng sáng bóng sang trọng. Dây đeo da phối xích có thể điều chỉnh đeo chéo hoặc xách tay linh hoạt.', N'Kích thước tiêu chuẩn: Chiều dài 24cm x Rộng 8cm x Cao 16cm (Chứa vừa iPad Mini, điện thoại, ví dài)', CAST(520000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.4866667' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2370, 2431, NULL, N'SP-BALO-LAPTOP-12', N'Balo Laptop Công Sở Kháng Nước Đa Năng Simplain 20L', N'balo-laptop-cong-so-khang-nuoc-simplain', N'Vải Canvas chống nước', N'Balo nắp cuộn (Roll-top)', N'Balo công sở thiết kế tối giản thông minh, chất vải Canvas 900D phủ tráng PU chống thấm nước khi đi mưa. Đệm lưng tổ ong thoáng khí thoát nhiệt, quai đeo trợ lực chống gù lưng hiệu quả.', N'Form chuẩn 20L: 43cm x 30cm x 14cm (Có ngăn chống sốc chuyên dụng đựng laptop 15.6 inch)', CAST(420000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.4933333' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2371, 2456, NULL, N'SP-VI-DABO-13', N'Ví Nam Da Bò Sáp Bifold Khâu Tay Thủ Công Cao Cấp', N'vi-nam-da-bo-sap-bifold-khau-tay', N'Da bò sáp nguyên tấm', N'Ví gập đôi Bifold', N'Ví nam da bò sáp Crazy Horse nhập khẩu nguyên tấm, càng sử dụng lâu chất da càng bóng mềm và lên màu vintage độc nhất. Từng đường kim mũi chỉ được khâu thủ công tỉ mỉ, độ bền trên 10 năm.', N'Kích thước gập: 11.5cm x 9.5cm x 1.5cm (Gồm 2 ngăn tiền chính và 8 ngăn thẻ ATM/CCCD)', CAST(290000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.5033333' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2372, 2435, NULL, N'SP-PK-DONGHO-14', N'Đồng Hồ Nam Dây Thép Không Gỉ Mặt Kính Sapphire Simplain Classic', N'dong-ho-nam-thep-khong-gi-mat-sapphire', N'Thép không gỉ 316L', N'Mặt tròn cổ điển', N'Đồng hồ nam phong cách doanh nhân lịch lãm, bộ máy Quartz chuẩn xác từ Nhật Bản. Toàn bộ vỏ và dây đeo chế tác từ thép không gỉ 316L chống ăn mòn tuyệt đối, mặt kính tinh thể Sapphire chống va đập trầy xước.', N'Đường kính mặt 40mm | Độ dày vỏ 8.5mm | Chiều dài dây 220mm (Kính Sapphire chống xước, chống nước 5ATM)', CAST(890000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.5133333' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2373, 2458, NULL, N'SP-PK-KINHMAT-15', N'Kính Mát Unisex Gọng Titanium Phân Cực Polarized Chống UV400', N'kinh-mat-unisex-gong-titanium-polarized', N'Titanium mạ PVD siêu bền', N'Mặt tròn cổ điển', N'Kính mát phân cực cao cấp gọng hợp kim Titanium siêu nhẹ, chịu lực uốn cong linh hoạt không biến dạng. Tròng kính tráng gương 9 lớp bảo vệ mắt tối đa khỏi 100% tia tử ngoại UV400 và chống lóa đèn xe ban đêm.', N'Chiều ngang tròng: 54mm | Cầu kính: 18mm | Chiều dài càng kính: 142mm (Khối lượng siêu nhẹ chỉ 18g)', CAST(350000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.5200000' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2374, 2459, NULL, N'SP-PK-MUNON-16', N'Mũ Lưỡi Trai Classic Simplain Thêu Nổi 100% Cotton', N'mu-luoi-trai-classic-simplain-cotton', N'Cotton Compact 100%', N'Mũ lưỡi trai (Cap)', N'Nón kết lưỡi trai form dáng 6 múi cứng cáp, thêu logo Simplain nổi 3D tinh xảo. Chất vải kaki cotton chải kỹ thấm hút mồ hôi tối ưu, đem lại cảm giác thoáng mát cả ngày dài dạo phố hay chơi thể thao.', N'Freesize: Vòng đầu từ 55 - 60cm (Khóa đồng phía sau có thể nới rộng / thu hẹp dễ dàng)', CAST(150000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.5300000' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2376, 2434, NULL, N'SP-PK-TRANGSUC-18', N'Vòng Tay Bạc Ý 925 Xi Bạch Kim Mắt Xích Cuban Nam Nữ', N'vong-tay-bac-y-925-cuban-chain', N'Bạc Ý 925 xi bạch kim', N'Dây xích Cuban cá tính', N'Lắc tay bạc chuẩn 92.5% phủ lớp mạ Rhodium bạch kim bóng bẩy, chống ố xỉn và không gây kích ứng da. Thiết kế mắt xích Cuban đan cài mạnh mẽ, phong cách streetwear thời thượng nâng tầm cổ tay.', N'Chiều dài lắc 18cm + 3cm mắt xích mở rộng (Bản xích dày 5mm, khối lượng 14.2 gram)', CAST(390000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.5466667' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2377, 2443, NULL, N'SP-PK-KHANCHOANG-19', N'Khăn Choàng Cổ Len Cashmere Giữ Ấm Mùa Đông Cao Cấp', N'khan-choang-co-len-cashmere-cao-cap', N'Len Cashmere cao cấp', N'Regular Fit', N'Khăn choàng cổ dệt từ sợi len Cashmere cao cấp kết hợp lông cừu tự nhiên, mang lại cảm giác mềm mại như nhung, không gây dặm ngứa da cổ. Hai đầu khăn đan tua rua cổ điển thanh lịch, giữ ấm cơ thể hoàn hảo trong ngày đông giá rét.', N'Kích thước tiêu chuẩn: Chiều dài 200cm x Rộng 70cm (Khối lượng 260g siêu nhẹ giữ nhiệt tối ưu)', CAST(310000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:49:55.5500000' AS DateTime2), NULL, NULL, NULL)
GO
INSERT [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2380, 2441, NULL, N'SP-PK-THAT-LUNG-17', N'Thắt Lưng Nam Da Bò Sáp Khóa Kim Loại Tự Động Cao Cấp', N'that-lung-nam-da-bo-khoa-tu-dong-cao-cap', N'Da bò sáp nguyên tấm', N'Regular Fit', N'Dây nịt nam da bò thuộc 2 lớp dẻo dai nguyên tấm, không bong tróc hay rạn nứt bề mặt. Khóa ray trượt tự động hợp kim mạ crom sáng bóng, thao tác cài mở êm mượt và sang trọng.', N'Bản rộng 3.5cm x Chiều dài 120cm (Phù hợp vòng bụng từ 75cm đến 105cm, dễ cắt bớt dây)', CAST(290000.00 AS Decimal(18, 2)), 1, 1, CAST(N'2026-11-05T15:51:14.7700000' AS DateTime2), NULL, NULL, NULL)
